import { execSync } from "node:child_process";

const checks = [
  { name: "Node >= 20", run: () => Number(process.versions.node.split(".")[0]) >= 20 },
  { name: "npm disponible", run: () => Boolean(execSync("npm --version")) },
  { name: "Git disponible", run: () => Boolean(execSync("git --version")) },
