console.log(largest([4, 9, 2])); // 9

const lineTotal = (line) => line.price * line.quantity;
const subtotal = (lines) => lines.reduce((sum, line) => sum + lineTotal(line), 0);
const applyDiscount = (amount, rate) => amount * (1 - rate);
const applyTax = (amount, rate) => amount * (1 + rate);
const round2 = (n) => Math.round(n * 100) / 100;

const lines = [{ price: 10, quantity: 2 }, { price: 5, quantity: 1 }];
