function average(numbers) {
  if (numbers.length === 0) return null; // caso límite: lista vacía
  const total = numbers.reduce((sum, n) => sum + n, 0);
  return total / numbers.length;
}

console.log(average([4, 8]));   // 6
console.log(average([5]));      // 5  (un elemento)
console.log(average([]));       // null (sin la guarda daría NaN)
console.log(average([-2, 2]));  // 0  (negativos)

