solution.code:
function buildInvoice(number, customer, lines, paid = false) {
  let totalInCents = 0;
  for (const line of lines) {
    totalInCents += line.priceInCents * line.quantity;
  }
  return {
    number,
    customer,
    lineCount: lines.length,
    totalInCents,
    isPaid: paid === true,
  };
}

