  // Tu solución
}

solution.code:
function collatzSteps(n) {
  if (!Number.isInteger(n) || n < 1) {
    throw new RangeError("n debe ser un entero mayor o igual que 1");
  }
  let steps = 0;
  let current = n;
  while (current !== 1) {
    current = current % 2 === 0 ? current / 2 : current * 3 + 1;
    steps++;
  }
  return steps;
}

