solution.code:
function differingRows(f, g) {
  const values = [true, false];
  const rows = [];
  for (const a of values) {
    for (const b of values) {
      for (const c of values) {
        if (f(a, b, c) !== g(a, b, c)) rows.push([a, b, c]);
      }
    }
  }
  return rows;
}

