// Contrato: recibe un string; devuelve true si tiene al menos 8 caracteres,
// un digito y una mayuscula (A-Z). Lanza TypeError si no es un string.
function isStrongPassword(password) {
  if (typeof password !== "string") {
    throw new TypeError("password debe ser un string");
  }
  return password.length >= 8 && /[0-9]/.test(password) && /[A-Z]/.test(password);
}

