function totalsByCustomer(orders) {
  const totals = new Map();
  for (const { customer, total } of orders) {
    totals.set(customer, (totals.get(customer) ?? 0) + total);
  }
  return totals;
}

function toEntries(totals) {
  return [...totals.entries()];
}

function pickTopName(entries) {
  let best = null;
  for (const entry of entries) {
    if (best === null || entry[1] > best[1]) best = entry;
  }
  return best === null ? null : best[0];
}

function topCustomer(orders) {
  return pickTopName(toEntries(totalsByCustomer(orders)));
}

