function addToCart(cart, sku, qty) {
  const exists = cart.some((line) => line.sku === sku);
  if (!exists) {
    return [...cart, { sku, qty }];
  }
  return cart.map((line) =>
    line.sku === sku ? { ...line, qty: line.qty + qty } : line,
  );
}

function removeFromCart(cart, sku) {
  return cart.filter((line) => line.sku !== sku);
}

