solution.code:
class Account {
  #balance = 0;

  constructor(owner) {
    this.owner = owner;
  }

  get balance() {
    return this.#balance;
  }

  get overdraftLimit() {
    return 0;
  }

  #validate(amount) {
    if (typeof amount !== 'number' || !Number.isFinite(amount) || amount <= 0) {
      throw new RangeError('El importe debe ser positivo');
    }
  }

  deposit(amount) {
    this.#validate(amount);
    this.#balance += amount;
    return this;
  }

  withdraw(amount) {
    this.#validate(amount);
    if (amount > this.#balance + this.overdraftLimit) {
      throw new Error('Fondos insuficientes');
    }
    this.#balance -= amount;
    return this;
  }
}

class OverdraftAccount extends Account {
  #limit;

  constructor(owner, limit) {
    super(owner);
    this.#limit = limit;
  }

  get overdraftLimit() {
    return this.#limit;
  }
}

spec.code:
