assert.strictEqual(acc.owner, 'Ana');
assert.strictEqual(acc.balance, 0);
assert.strictEqual(acc.deposit(100).withdraw(100).balance, 0);

const acc = new Account('Ana').deposit(40);
assert.throws(() => acc.withdraw(41), Error);
assert.strictEqual(acc.balance, 40);

const acc = new Account('Ana').deposit(10);
for (const bad of [0, -5, NaN, Infinity, '10', null, undefined]) {
  assert.throws(() => acc.deposit(bad), RangeError);
  assert.throws(() => acc.withdraw(bad), RangeError);
}
assert.strictEqual(acc.balance, 10);

const acc = new Account('Ana');
assert.ok(!Object.hasOwn(acc, 'balance'));
