solution.code:
function spendingByCategory(transactions) {
  const totals = transactions.reduce((acc, t) => {
    acc[t.category] = (acc[t.category] ?? 0) + t.amount;
    return acc;
  }, {});
  const top = Object.keys(totals).reduce((best, name) => {
    if (best === null) return name;
    if (totals[name] > totals[best]) return name;
    if (totals[name] === totals[best] && name < best) return name;
    return best;
  }, null);
  return { totals, top };
}

