solution.code:
function setIn(obj, path, value) {
  if (path.length === 0) return value;
  const [key, ...rest] = path;
  const base = obj === undefined || obj === null ? {} : obj;
  const copy = Array.isArray(base) ? [...base] : { ...base };
  copy[key] = setIn(base[key], rest, value);
  return copy;
}

