solution.code:
function pipe(...fns) {
  return (x) => fns.reduce((value, fn) => fn(value), x);
}

function slugify(text) {
  const trim = (s) => s.trim();
  const lower = (s) => s.toLowerCase();
  const noAccents = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const dashes = (s) => s.replace(/\s+/g, '-');
  const limit = (s) => s.slice(0, 20).replace(/-+$/, '');
  return pipe(trim, lower, noAccents, dashes, limit)(text);
}

