solution.code:
class ConfigError extends Error {
  constructor(message, options) {
    super(message, options);
    this.name = "ConfigError";
  }
}

function parseConfig(text) {
  let config;
  try {
    config = JSON.parse(text);
  } catch (error) {
    throw new ConfigError("La configuración no es un JSON válido", { cause: error });
  }
  if (config === null || typeof config !== "object" || !("port" in config)) {
    throw new ConfigError('Falta el campo obligatorio "port"');
  }
  return config;
}

