solution.code:
class FileNotFoundError extends Error {
  constructor(fileName, options) {
    super(`Archivo no encontrado: ${fileName}`, options);
    this.name = "FileNotFoundError";
    this.fileName = fileName;
  }
}

class InvalidFormatError extends Error {
  constructor(fileName, options) {
    super(`Formato inválido en ${fileName}`, options);
    this.name = "InvalidFormatError";
    this.fileName = fileName;
  }
}

function readOrders(files, name) {
  if (!(name in files)) {
    throw new FileNotFoundError(name);
  }
  const raw = files[name];
  let data;
  try {
    data = JSON.parse(raw);
  } catch (error) {
    throw new InvalidFormatError(name, { cause: error });
  }
  if (!Array.isArray(data)) {
    throw new InvalidFormatError(name);
  }
  return data;
}

function loadOrdersMessage(files, name) {
  try {
    const orders = readOrders(files, name);
    return `Pedidos cargados: ${orders.length}`;
  } catch (error) {
    if (error instanceof FileNotFoundError) {
      return `No se encontró el archivo "${name}"`;
    }
    if (error instanceof InvalidFormatError) {
      return `El archivo "${name}" tiene un formato inválido`;
    }
    throw error;
  }
}

