solution.code:
function readAll(files, read, cb) {
  const results = [];
  function next(index) {
    if (index === files.length) return cb(null, results);
    read(files[index], (err, content) => {
      if (err) return cb(err);
      results.push(content);
      next(index + 1);
    });
  }
  next(0);
}

