solution.code:
async function loadDashboard(api) {
  const [profile, orders, notifications] = await Promise.allSettled([
    api.getProfile(),
    api.getOrders(),
    api.getNotifications(),
  ]);
  if (profile.status === 'rejected') throw profile.reason;
  if (orders.status === 'rejected') throw orders.reason;
  const notificationsOk = notifications.status === 'fulfilled';
  return {
    profile: profile.value,
    orders: orders.value,
    notifications: notificationsOk ? notifications.value : [],
    warning: notificationsOk ? null : 'No se pudieron cargar las notificaciones',
  };
}

