@Catch()
export class AllExceptionsFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost) {
    const response = host.switchToHttp().getResponse<Response>();
    const traceId = randomUUID();

    if (exception instanceof HttpException) {
      const status = exception.getStatus();
      response.status(status).json({ error: { code: "...", message: exception.message, traceId } });
      return;
    }

    // Error no previsto: nunca exponer detalles internos
    console.error(`[${traceId}]`, exception);
    response.status(500).json({ error: { code: "INTERNAL_ERROR", message: "Algo salió mal", traceId } });
  }
}

async cancelar(pedidoId: string, usuarioId: string) {
  const pedido = await this.repo.buscar(pedidoId);
  if (!pedido) throw new NotFoundException("Pedido no encontrado"); // 404
  if (pedido.usuarioId !== usuarioId) throw new ForbiddenException("No autorizado"); // 403
  if (pedido.estado === "entregado") {
    throw new ConflictException("No se puede cancelar un pedido ya entregado"); // 409
  }
  return this.repo.cancelar(pedidoId);
}

