async function ejecutarHerramienta(nombre: string, parametrosCrudos: unknown, usuarioActual: Usuario) {
  if (nombre !== "consultarEstadoPedido") throw new Error("Herramienta desconocida");
  const { pedidoId } = herramientaConsultarPedido.parametros.parse(parametrosCrudos); // valida, igual que E5

  const pedido = await pedidosService.buscar(pedidoId);
  if (pedido.usuarioId !== usuarioActual.id) throw new ForbiddenException(); // autorización real, E5-U5.3.3

  return { estado: pedido.estado, fechaEstimada: pedido.fechaEstimada };
}

function construirContextoConversacion(historial: AiMessage[], limiteReciente = 6): AiMessage[] {
  if (historial.length <= limiteReciente) return historial;

  const antiguos = historial.slice(0, -limiteReciente);
  const recientes = historial.slice(-limiteReciente);

  const resumen: AiMessage = {
    role: "system",
    content: `Resumen de la conversación anterior: ${resumirBreve(antiguos)}`,
  };

  return [resumen, ...recientes]; // contexto acotado, no todo el historial crudo
}

async function responderConRAG(pregunta: string): Promise<string> {
  const embeddingPregunta = await generarEmbedding(pregunta);
  const fragmentosRelevantes = await buscarSimilar(embeddingPregunta, baseDeConocimiento, 3);

  const contexto = fragmentosRelevantes.map((f) => f.texto).join("\n\n");

  const mensajes: AiMessage[] = [
    { role: "system", content: "Responde ÚNICAMENTE basándote en el siguiente contexto. Si la respuesta no está en el contexto, dilo explícitamente." },
    { role: "user", content: `Contexto:\n${contexto}\n\nPregunta: ${pregunta}` },
  ];

  return (await proveedor.complete(mensajes)).content;
}

function dividirEnFragmentos(texto: string, tamanoMax = 500, solapamiento = 50): string[] {
  const palabras = texto.split(" ");
  const fragmentos: string[] = [];

  for (let i = 0; i < palabras.length; i += tamanoMax - solapamiento) {
    fragmentos.push(palabras.slice(i, i + tamanoMax).join(" "));
  }

  return fragmentos; // cada fragmento comparte 'solapamiento' palabras con el siguiente
}

