function medirFidelidad(respuesta: string, fragmentosContexto: string[]): number {
  const afirmaciones = extraerAfirmaciones(respuesta); // simplificado
  const respaldadas = afirmaciones.filter((afirmacion) =>
    fragmentosContexto.some((fragmento) => respaldaAfirmacion(fragmento, afirmacion)),
  );
  return respaldadas.length / afirmaciones.length;
}
